INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Laboratório de IA conversacional aplicado ao contexto acadêmico', 'curso', 'Inteligência Artificial & Dados', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5474-laboratorio-de-ia-conversacional-aplicado-ao-contexto-academico', 'gratuito', 'Intermediário', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Curso prático e dinâmico sobre o uso de chats conversacionais para profissionais da área de Educação. Modalidade: Online (São Paulo). Carga horária: 2h. Instrutor(a): Edilson Gabriel Veruz. Conteúdo programático: O aluno irá participar de um laboratório onde serão apresentadas várias formas práticas de utilização de ferramentas de Inteligência Artificial para educação. Será dada ênfase a criação e automatização de prompts. Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5474-laboratorio-de-ia-conversacional-aplicado-ao-contexto-academico');
