INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Fundamentos de Bancos de Dados SQL para Saúde Digital', 'curso', 'Desenvolvimento Web & Mobile', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5487-fundamentos-de-bancos-de-dados-sql-para-saude-digital', 'gratuito', 'Iniciante', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Curso introdutório e prático de bancos de dados relacionais e SQL contextualizado em Saúde Digital. Utilizando um ambiente SQL online compatível com SQLite, diretamente no navegador, os participantes irão modelar um pequeno banco com pacientes codificados, dispositivos e medições sintéticas, criar tabelas, inserir registros e realizar consultas para responder perguntas sobre o conjunto de dados. Serão trabalhados conceitos de tabelas, chaves, relacionamentos, integridade e operações SQL essenciais. Modalidade: Online (Brasília). Carga horária: 3h. Instrutor(a): Guillermo Alvarez Bestard. Conteúdo programático: Diferença entre planilhas/CSV, bancos de dados e sistemas gerenciadores de bancos de dados; - Modelo relacional: tabelas, registros, campos e tipos de dados; - Chaves primárias, chaves estrangeiras e relacionamentos; - Noção prática de normalizaçã... Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5487-fundamentos-de-bancos-de-dados-sql-para-saude-digital');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Watch Face Studio: Construção de Watch Faces com Wear OS 5', 'curso', 'DevOps, Cloud & Infraestrutura', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5529-watch-face-studio-construcao-de-watch-faces-com-wear-os-5', 'gratuito', 'Intermediário', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Apresentar o Watch Face Studio, uma ferramenta gráfica e gratuita totalmente no code, para construção de mostradores (watch faces) para o ecossistema de smartwatches que adotam o Wear OS. O aluno aprenderá a personalizar seu smartwatch com o design e as funcionalidades que desejar sem a necessidade de conhecimentos avançados em programação. Modalidade: Presencial (Manaus). Carga horária: 3h. Instrutor(a): Isaac Benjamim Benchimol. Conteúdo programático: O ambiente Watch Face Studio para Windows Estilo: cor, fonte, imagens, fundo Complicações Animações Aplicação com sensor giroscópio Conexão, transmissão e teste do watch face com o smartwatch Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5529-watch-face-studio-construcao-de-watch-faces-com-wear-os-5');
