INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Publicação Online de Aplicações: HTML, CSS e React no Render', 'curso', 'Desenvolvimento Web & Mobile', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5551-publicacao-online-de-aplicacoes-html-css-e-react-no-render', 'gratuito', 'Intermediário', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Este curso prático visa ensinar o fluxo completo de publicação de aplicações web, desde sites estáticos simples (HTML/CSS) até aplicações modernas desenvolvidas em React. O foco é automatizar o processo de deploy utilizando a integração contínua entre o GitHub e o Render, permitindo que o estudante aprenda a colocar seus projetos no ar de forma gratuita, segura e com atualizações automáticas a cada novo "push" no repositório. Modalidade: Online (Brasília). Carga horária: 2h. Instrutor(a): Luiz Henrique Morais Aguiar. Conteúdo programático: • Configuração e organização de repositórios no GitHub para garantir um deploy sem erros. • Como vincular sua conta do GitHub à plataforma Render para monitoramento de projetos. • Publicação de sites básicos (HTML, CSS e JS) utilizando o serviço d... Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5551-publicacao-online-de-aplicacoes-html-css-e-react-no-render');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Redes Neurais na Saúde I — Fundamentos e Primeiros Modelos', 'curso', 'Inteligência Artificial & Dados', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5546-redes-neurais-na-saude-i-fundamentos-e-primeiros-modelos', 'gratuito', 'Iniciante', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Curso introdutório e prático para compreender, desde o zero, como funcionam neurônios artificiais e redes neurais, utilizando exemplos da área da saúde. O participante aprenderá os conceitos fundamentais de entrada, pesos, viés, função de ativação, treinamento e erro; visualizará o aprendizado de uma rede no TensorFlow Playground e executará seu primeiro modelo no Google Colab, sem necessidade de experiência prévia em inteligência artificial. Modalidade: Online (Brasília). Carga horária: 2h. Instrutor(a): Gerardo Antonio Idrobo Pizo. Conteúdo programático: Fundamentos de neurônios e redes neurais Entradas, pesos, ativação e treinamento Uso do TensorFlow Playground Criação do primeiro modelo no Google Colab Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5546-redes-neurais-na-saude-i-fundamentos-e-primeiros-modelos');
