INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Usabilidade e Acessibilidade em Saúde Digital: do Usuário ao Teste da Solução', 'curso', 'UI/UX & Design', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5536-usabilidade-e-acessibilidade-em-saude-digital-do-usuario-ao-teste-da-solucao', 'gratuito', 'Intermediário', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Curso introdutório-aplicado que utiliza situações reais de uso para analisar como usuários, tarefas, interfaces e contexto influenciam a usabilidade, a acessibilidade e a segurança de tecnologias de Saúde Digital. Os participantes irão avaliar uma solução, identificar barreiras e propor melhorias justificadas com base em princípios de design centrado no usuário e em métodos introdutórios de teste. Modalidade: Online (Brasília). Carga horária: 2h. Instrutor(a): Glécia Virgolino da Silva Luz. Conteúdo programático: -Conceitos de usabilidade, experiência do usuário (UX) e interface do usuário (UI). -Usuários, stakeholders, tarefas, contexto de uso e workflow. -Jornada do usuário e identificação de necessidades. -Design centrado no ser humano e co-design. -Ace... Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5536-usabilidade-e-acessibilidade-em-saude-digital-do-usuario-ao-teste-da-solucao');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Introdução ao Blockchain para iniciantes', 'curso', 'Desenvolvimento Web & Mobile', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/5096-introducao-ao-blockchain-para-iniciantes', 'gratuito', 'Iniciante', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). O blockchain armazena periodicamente informações de transações em lotes, chamados blocos. Esses blocos recebem uma impressão digital chamada hash – um código matemático único – e são interligados em um conjunto em ordem cronológica, formando uma linha contínua de blocos – uma corrente (daí o termo “chain”) Modalidade: EAD (Manaus). Carga horária: 4h. Instrutor(a): Moisés Pereira Bastos. Conteúdo programático: Introdução ao Blockchain; Tipos de Blockchain; Aplicações de Blockchain; Plataformas de Blockchain; Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/5096-introducao-ao-blockchain-para-iniciantes');
