INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Ocean Cast #12 - Ciência de Dados e IA na área de Finanças', 'curso', 'Inteligência Artificial & Dados', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/4036-ocean-cast-12-ciencia-de-dados-e-ia-na-area-de-financas', 'gratuito', 'Intermediário', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Neste episódio do Ocean Cast os professores Tiago Melo e Maurício Figueiredo conversam com a professora Izabel Nogueira, especialista em administração financeira, sobre a aplicação da inteligência artificial (IA) no setor financeiro. Modalidade: EAD (Manaus). Carga horária: 4h. Instrutor(a): Carlos Maurício Seródio Figueiredo, Tiago Eugenio de Melo . Conteúdo programático: A professora Izabel Seabra discute como a IA está transformando a indústria, desde a customização de serviços até a análise de dados e a previsão de mercado, e explora os desafios e oportunidades que essa tecnologia apresenta. Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/4036-ocean-cast-12-ciencia-de-dados-e-ia-na-area-de-financas');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Introdução à Inteligência Artificial', 'curso', 'Inteligência Artificial & Dados', 'Samsung Ocean', 'https://oceanbrasil.com/atividades/4524-introducao-a-inteligencia-artificial', 'gratuito', 'Iniciante', 'Curso oficial gratuito da Samsung Ocean em parceria com a Universidade de São Paulo (USP) e Universidade do Estado do Amazonas (UEA). Vivemos na era dos dados e da inteligência artificial. Este curso foi criado para te apresentar, de forma simples e prática, os conceitos essenciais que estão transformando o nosso mundo. Curso introdutório 100% online e gratuito, com linguagem acessível, ideal para quem está começando. Com aulas curtas, quizzes interativos e exemplos do dia a dia, você aprenderá o que é IA e Ciência de Dados como impactam em nossas vidas. Modalidade: EAD (Manaus). Carga horária: 4h. Instrutor(a): Rubelmar Maia de Azevedo Cruz Neto. Conteúdo programático: Introdução de IA e Ciência de Dados Aprendizado supervisionado vs. não supervisionado Fundamentos de regressão e classificação Redes neurais e aplicações como reconhecimento de imagem Engenharia de prompt com IA generativa (como o ChatGPT) Ética, ... Certificado oficial gratuito emitido pela Samsung Ocean.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://oceanbrasil.com/atividades/4524-introducao-a-inteligencia-artificial');
